                float distance = (float)Math.Sqrt(dx * dx + dy * dy);
                float step = _workingLeashed?Math.Min(4.5f,Math.Max(1.5f,distance-1f)):Math.Min(28f, Math.Max(12f, distance - 2f));
                float inv = distance > .01f ? 1f / distance : 0f;
